<style>
  body {
    background: #eae7e0;
    margin: 0;
    padding: 0;
    font-family: Georgia, 'Times New Roman', serif;
    display: flex;
    justify-content: center;
  }
  .poster {
    width: 540px;
    min-height: 760px;
    background: #fff;
    border: 6px solid #e8452c;
    box-sizing: border-box;
    padding: 8px;
    position: relative;
    margin: 10px;
  }
  .tagline {
    text-align: center;
    color: #e8452c;
    font-size: 20px;
    font-weight: bold;
    font-style: italic;
    margin: 6px 0 6px 0;
    letter-spacing: 0.5px;
  }
  .placeholder {
    width: 100%;
    height: 330px;
    background: repeating-linear-gradient(45deg, #ddd, #ddd 10px, #eee 10px, #eee 20px);
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: #555;
    font-size: 13px;
    border: 1px solid #bbb;
    box-sizing: border-box;
    margin-bottom: 4px;
  }
  .title-block {
    text-align: center;
    margin-top: 6px;
  }
  .title-main {
    color: #e8452c;
    font-size: 30px;
    font-weight: bold;
    letter-spacing: 1px;
    line-height: 1.1;
  }
  .subtitle-original {
    font-size: 12px;
    margin-top: 4px;
    color: #222;
  }
  .credits-line {
    font-size: 11px;
    text-align: center;
    margin: 2px 0;
    color: #222;
  }
  .cast-block {
    text-align: center;
    margin-top: 10px;
    font-size: 14px;
    font-weight: bold;
    color: #111;
    line-height: 1.5;
  }
  .costars {
    text-align: center;
    margin-top: 6px;
    font-size: 11px;
    color: #222;
  }
  .costars b {
    font-weight: bold;
  }
  .music {
    text-align: center;
    font-size: 10px;
    margin-top: 2px;
    color: #333;
  }
  .bottom-credits {
    display: flex;
    font-size: 8.5px;
    color: #222;
    margin-top: 10px;
    justify-content: space-between;
  }
  .bottom-col {
    flex: 1;
    text-align: center;
    padding: 0 2px;
  }
  .footer-row {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-top: 14px;
    font-size: 9px;
  }
  .footer-left {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
  }
  .nueva-films {
    background: #000;
    color: #fff;
    font-weight: bold;
    font-size: 11px;
    padding: 3px 6px;
  }
  .delphi {
    margin-top: 4px;
    font-size: 9px;
    letter-spacing: 1px;
  }
  .footer-right {
    text-align: right;
    font-size: 7px;
    color: #333;
    max-width: 160px;
  }
  .dolby-box {
    border: 1px solid #333;
    display: inline-block;
    padding: 1px 4px;
    font-size: 7px;
    margin-top: 2px;
  }
  .circle-logo {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: #ccc;
    display: inline-block;
    margin-left: 4px;
    text-align: center;
    font-size: 6px;
    line-height: 34px;
    color: #555;
  }
</style>
