      PRODUCTORES EJECUTIVOS<br>
      NED TANEN Y BERNARD SCHWARTZ
    </div>
  </div>

  <div class="bottom-credits" style="margin-top:4px;">
    <div class="bottom-col">
      ESCRITA POR JOEL SCHUMACHER Y CARL KURLANDER
    </div>
    <div class="bottom-col">
      DIRIGIDA POR JOEL SCHUMACHER
    </div>
    <div class="bottom-col">
      PRODUCIDA POR LAUREN SHULER
